('r31-saumon-pesto-rouge-haricots','Saumon au pesto rouge, haricots plats','Laqué. Piquant. Croquant.','main','poisson',25,2,9,36,520,array['four','réchauffable']::text[],'[{"name": "pavé de saumon", "qty": 4, "unit": "pièce", "rayon": "Poissonnerie"}, {"name": "haricots plats", "qty": 600, "unit": "g", "rayon": "Légumes"}, {"name": "pesto rouge", "qty": 4, "unit": "c. à s.", "rayon": "Épicerie"}, {"name": "jalapeños en bocal", "qty": 40, "unit": "g", "rayon": "Épicerie"}, {"name": "parmesan râpé", "qty": 40, "unit": "g", "rayon": "Crèmerie"}, {"name": "herbes de Provence", "qty": 1, "unit": "c. à c.", "rayon": "Épicerie"}]'::jsonb,array['Four 200 °C. Haricots plats 6 min à l''eau bouillante, égouttés.','Pavés sur plaque, badigeonnés de pesto rouge, herbes.','12 min au four, haricots autour les 5 dernières minutes.','Jalapeños et parmesan au service.']::text[],true,'seed'),
